using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class LibraryMembershipConfiguration : IEntityTypeConfiguration<LibraryMembership>
{
    public void Configure(EntityTypeBuilder<LibraryMembership> builder)
    {
        builder.ToTable("library_memberships", t =>
        {
            t.HasCheckConstraint("CK_library_memberships_status", "[status] IN (N'active', N'suspended')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.CardNo).HasColumnName("card_no").HasColumnType("nvarchar(30)").HasMaxLength(30).IsRequired();
        builder.Property(e => e.MemberSince).HasColumnName("member_since").HasColumnType("date");
        builder.Property(e => e.ValidUntil).HasColumnName("valid_until").HasColumnType("date");
        builder.Property(e => e.MaxBooks).HasColumnName("max_books");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'active'");
        builder.Property(e => e.Notes).HasColumnName("notes").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.HasIndex(e => e.StudentId).IsUnique();
        builder.HasIndex(e => e.CardNo).IsUnique();
        builder.HasOne(e => e.Student).WithOne(p => p.LibraryMembership).HasForeignKey<LibraryMembership>(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
